-- CALLORIA Phase 4: additive knowledge base for RuffNeck products, services and customer guidance.
-- Safe migration: creates only calloria_kb_* tables; does not alter shared Prospector tables, policies, triggers or existing CALLORIA tables.
create table if not exists public.calloria_kb_platforms (
 id text primary key, name text not null, url text not null, purpose text not null, features jsonb not null default '[]'::jsonb, support_topics jsonb not null default '[]'::jsonb, self_service jsonb not null default '[]'::jsonb, limitations text, verified_at timestamptz not null default now(), active boolean not null default true
);
create table if not exists public.calloria_kb_services (
 slug text primary key, name text not null, description text not null, category text not null default 'service', active boolean not null default true, updated_at timestamptz not null default now()
);
create table if not exists public.calloria_kb_articles (
 slug text primary key, title text not null, category text not null, body text not null, tags text[] not null default '{}', audience text not null default 'customer', status text not null default 'published' check (status in ('draft','published','retired')), reviewed_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.calloria_kb_safety_rules (
 rule_key text primary key, severity text not null check (severity in ('info','caution','high','critical')), instruction text not null, active boolean not null default true
);
create index if not exists calloria_kb_articles_category_idx on public.calloria_kb_articles(category);
create index if not exists calloria_kb_articles_tags_idx on public.calloria_kb_articles using gin(tags);
create index if not exists calloria_kb_services_category_idx on public.calloria_kb_services(category);
alter table public.calloria_kb_platforms enable row level security;
alter table public.calloria_kb_services enable row level security;
alter table public.calloria_kb_articles enable row level security;
alter table public.calloria_kb_safety_rules enable row level security;
-- Public read is intentional: this is customer-facing product knowledge, not customer records or secrets.
drop policy if exists calloria_kb_platforms_public_read on public.calloria_kb_platforms;
create policy calloria_kb_platforms_public_read on public.calloria_kb_platforms for select to anon, authenticated using (active = true);
drop policy if exists calloria_kb_services_public_read on public.calloria_kb_services;
create policy calloria_kb_services_public_read on public.calloria_kb_services for select to anon, authenticated using (active = true);
drop policy if exists calloria_kb_articles_public_read on public.calloria_kb_articles;
create policy calloria_kb_articles_public_read on public.calloria_kb_articles for select to anon, authenticated using (status = 'published');
drop policy if exists calloria_kb_safety_rules_public_read on public.calloria_kb_safety_rules;
create policy calloria_kb_safety_rules_public_read on public.calloria_kb_safety_rules for select to anon, authenticated using (active = true);






